import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2 } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create group for the sprite
  const group = new THREE.Group();
  group.position.set(-3.2, 1, 0.06);

  // Atlas region: 512x320 pixels
  const atlasWidth = 512;
  const atlasHeight = 320;
  const aspectRatio = atlasWidth / atlasHeight;

  // Create plane geometry with atlas aspect ratio
  const planeGeometry = new THREE.PlaneGeometry(aspectRatio * 1.5, 1.5);

  // Load texture and create material
  ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
    texture.colorSpace = THREE.SRGBColorSpace;

    // Calculate UV region for atlas (assuming atlas is 512x320, region is full)
    const uvOffset = new THREE.Vector2(0, 0);
    const uvScale = new THREE.Vector2(1, 1);

    texture.offset.copy(uvOffset);
    texture.repeat.copy(uvScale);

    // Create material with texture node
    const material = new MeshBasicNodeMaterial({
      colorNode: texture,
      transparent: true,
      side: THREE.DoubleSide,
      depthTest: true,
      depthWrite: false,
    });

    const plane = new THREE.Mesh(planeGeometry, material);
    group.add(plane);
  });

  // Create text label "Collection 1"
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const labelItem = textItems.find((item) => item.text === 'Collection 1');

  if (labelItem) {
    const textObj = ctx.fontAtlas.createText('Collection 1', {
      fontSize: 39,
      color: '#e8ecf2',
      align: 'center',
    });
    textObj.position.set(0, -1.0, 0.1);
    group.add(textObj);
  }

  // Setup cleanup
  group.userData.cleanup = () => {
    planeGeometry.dispose();
  };

  return group;
}
